import React from "react";
import { Excalidraw } from "../index";
import { LinearElementEditor } from "../element/linearElementEditor";
import { pointFrom } from "../../math";
import { API } from "./helpers/api";
import { Pointer } from "./helpers/ui";
import { render } from "./test-utils";

const { h } = window;

describe("arrow endpoint binding regression", () => {
  beforeEach(async () => {
    localStorage.clear();
    await render(<Excalidraw handleKeyboardGlobally={true} />);
  });

  it(
    "[excalidraw-9010-endpoint-stability] keeps the untouched binding point stationary while dragging the other endpoint",
    () => {
      const source = API.createElement({
        type: "rectangle",
        id: "source-9010",
        x: 0,
        y: 0,
        width: 100,
        height: 100,
        boundElements: [{ id: "arrow-9010", type: "arrow" }],
      });
      const destination = API.createElement({
        type: "rectangle",
        id: "destination-9010",
        x: 300,
        y: -200,
        width: 100,
        height: 100,
      });
      const arrow = API.createElement({
        type: "arrow",
        id: "arrow-9010",
        x: 110,
        y: 50,
        width: 500,
        height: 0,
        points: [pointFrom(0, 0), pointFrom(500, 0)],
        startBinding: {
          elementId: source.id,
          fixedPoint: null,
          focus: 0,
          gap: 10,
        },
        endBinding: null,
      });

      API.setElements([source, destination, arrow]);
      API.setAppState({
        selectedElementIds: { [arrow.id]: true },
        selectedLinearElement: new LinearElementEditor(arrow),
      });

      const readPoint = (index: number) =>
        LinearElementEditor.getPointAtIndexGlobalCoordinates(
          arrow,
          index,
          h.app.scene.getNonDeletedElementsMap(),
        );

      const startBefore = readPoint(0);
      const endBefore = readPoint(-1);
      const observedStartPoints = [startBefore];
      const mouse = new Pointer("mouse");

      mouse.downAt(endBefore[0], endBefore[1]);
      observedStartPoints.push(readPoint(0));
      mouse.moveTo(500, 200);
      observedStartPoints.push(readPoint(0));
      mouse.moveTo(
        destination.x,
        destination.y + destination.height / 2,
      );
      observedStartPoints.push(readPoint(0));
      mouse.upAt(destination.x, destination.y + destination.height / 2);
      observedStartPoints.push(readPoint(0));

      observedStartPoints.forEach((point) => {
        expect(point[0]).toBeCloseTo(startBefore[0], 5);
        expect(point[1]).toBeCloseTo(startBefore[1], 5);
      });

      expect(arrow.startBinding?.elementId).toBe(source.id);
      expect(arrow.endBinding?.elementId).toBe(destination.id);
      expect(source.boundElements).toEqual(
        expect.arrayContaining([{ id: arrow.id, type: "arrow" }]),
      );
      expect(destination.boundElements).toEqual(
        expect.arrayContaining([{ id: arrow.id, type: "arrow" }]),
      );
    },
  );
});
